class Solution:
    def twoSum(self, numbers: list[int], target: int) -> list[int]:
        keep_track_idx = {}
        for idx in range(len(numbers)):
            if numbers[idx] not in keep_track_idx:
                keep_track_idx[numbers[idx]] = [idx+1]
            else: keep_track_idx[numbers[idx]].append(idx+1)

        possibles = []
        for elem in numbers[::-1]:
            does_exist = target - elem
            if does_exist in numbers:
                possibles.append(tuple(sorted([elem, does_exist])))
            else:
                numbers.remove(elem)

        # print(possibles)

        # print(set(numbers))
        def length_is_1(possibles):
            # print(possibles)
            left = list(set(possibles))[0][0]
            right = list(set(possibles))[0][1]
            # print(left, right)
            res = []
            if left != right:
                res.append((keep_track_idx[left][0], keep_track_idx[right][0]))
            else:
                ""
                print(possibles[0])
                res.append((keep_track_idx[possibles[0][0]]))
            # print(keep_track_idx)
            # res.append((keep_track_idx[left][0], keep_track_idx[right][1]))
            # print(list(res))
            return list(res[0])


        if len(set(numbers)) == 2:
            res = length_is_1(possibles)
            return res

        # elif len(set(numbers)) == 3:
        #     num1, num2, num3 = set(numbers)
        #     print(num1, num2, num3 )
        #     if num1*2 == target:
        #         possibles.remove(num1)
        #     if num2*2 == target:
        #         possibles.remove(num2)
        #     if num3*2 == target:
        #         possibles.remove(num3)
        # print(possibles)

        else:
            for elem in possibles:
                a,b = elem
                if a == b:
                    possibles.remove(elem)
            # print(possibles)
            return length_is_1(possibles)


            # res = length_is_1(possibles)
            # return res

